DROP TABLE IF EXISTS editorial_label_seed_0019;
CREATE TABLE editorial_label_seed_0019 (question_id TEXT PRIMARY KEY, player_name TEXT NOT NULL, season INTEGER NOT NULL, season_label TEXT NOT NULL, trait_id TEXT NOT NULL, verdict TEXT NOT NULL CHECK (verdict IN ('qualifies','does_not_qualify')), note TEXT);
INSERT OR IGNORE INTO trait_questions_v1
  (id, trait_id, player_name, season, season_label, player_key, prompt_override, status, editorial_priority, definition_version, created_at, updated_at)
SELECT question_id, trait_id, player_name, season, season_label, NULL, NULL, 'active', 35, 1, CAST(strftime('%s','now') AS INTEGER) * 1000, CAST(strftime('%s','now') AS INTEGER) * 1000
FROM editorial_label_seed_0019;
INSERT OR IGNORE INTO trait_editorial_v1 (question_id, verdict, note, created_at)
SELECT question_id, verdict, note, CAST(strftime('%s','now') AS INTEGER) * 1000
FROM editorial_label_seed_0019;
INSERT OR IGNORE INTO trait_question_meta_v1
  (question_id, slug, public_question, what_counts, metadata_line, homepage_eligible, share_preview, active, created_at)
SELECT s.question_id,
       s.question_id,
       CASE s.trait_id
    WHEN 'three-point-shooter' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Three-Point Shooter?'
    WHEN 'super-three-point-shooter' THEN 'Did ' || s.season || ' ' || s.player_name || ' have game-breaking three-point gravity?'
    WHEN 'iso-defender' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Iso Defender?'
    WHEN 'team-defender' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Team Defender?'
    WHEN 'rim-protector' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Rim Protector?'
    WHEN 'playmaker' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Playmaker?'
    WHEN 'clutch' THEN 'Was ' || s.season || ' ' || s.player_name || ' clutch?'
    WHEN 'rim-pressurer' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Rim Pressurer?'
    WHEN 'off-ball-scorer' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Off-Ball Scorer?'
    WHEN 'switchable-defender' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Switchable Defender?'
    WHEN 'tough-shot-maker' THEN 'Was ' || s.season || ' ' || s.player_name || ' an elite Tough Shot Maker?'
    WHEN 'off-court-knucklehead' THEN 'Was ' || s.season || ' ' || s.player_name || ' an Off-Court Knucklehead?'
    WHEN 'ball-stopper' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Ball Stopper?'
    WHEN 'foul-merchant' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Foul Merchant?'
    WHEN 'stat-padder' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Stat Padder?'
    WHEN 'championship-number-one' THEN 'Could ' || s.season || ' ' || s.player_name || ' have been the #1 on a championship team?'
    WHEN 'ball-pounder' THEN 'Was ' || s.season || ' ' || s.player_name || ' a Ball Pounder?'
    ELSE 'Was ' || s.season || ' ' || s.player_name || ' ' || t.display_name || '?'
  END,
       t.short_definition,
       s.player_name || ' · ' || s.season_label,
       0,
       upper(CAST(s.season AS TEXT) || ' ' || s.player_name || ' · ' || t.display_name || '?'),
       1,
       CAST(strftime('%s','now') AS INTEGER) * 1000
FROM editorial_label_seed_0019 s
JOIN traits_v1 t ON t.id = s.trait_id;
DROP TABLE editorial_label_seed_0019;
